*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:           #0f1117;
  --color-surface:      #181c27;
  --color-surface-2:    #1f2438;
  --color-border:       #2e3550;
  --color-border-hover: #4a5578;
  --color-text:         #e2e6f0;
  --color-text-muted:   #8891aa;
  --color-accent:       #5b8dee;
  --color-accent-hover: #7aa4f5;
  --color-danger:       #e05260;
  --color-danger-hover: #f06070;
  --color-danger-bg:    rgba(224, 82, 96, 0.12);
  --color-focus-ring:   #5b8dee;
  --radius-sm:          6px;
  --radius-md:          10px;
  --radius-lg:          16px;
  --shadow-dialog:      0 24px 64px rgba(0, 0, 0, 0.7), 0 4px 16px rgba(0, 0, 0, 0.5);
}

html { color-scheme: dark; }

body {
  font-family: system-ui, -apple-system, "Segoe UI", Helvetica, Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  background-color: var(--color-bg);
  color: var(--color-text);
  min-height: 100dvh;
}

/* ─── Accessibility: skip link ──────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--color-accent);
  color: #fff;
  border-radius: var(--radius-sm);
  text-decoration: none;
  font-weight: 600;
  z-index: 9999;
  transition: top 0.1s;
}
.skip-link:focus { top: 1rem; }

/* ─── Focus ring ────────────────────────────────────────── */
:focus-visible {
  outline: 2px solid var(--color-focus-ring);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* ─── Header ────────────────────────────────────────────── */
.site-header {
  border-bottom: 1px solid var(--color-border);
  background: var(--color-surface);
}
.site-header__inner {
  max-width: 960px;
  margin: 0 auto;
  padding: 0.875rem 1.5rem;
  display: flex;
  align-items: center;
  gap: 0.625rem;
}
.site-header__logo {
  font-size: 1.25rem;
  color: var(--color-accent);
}
.site-header__name {
  font-weight: 600;
  font-size: 1.05rem;
  letter-spacing: 0.01em;
}

/* ─── Main layout ───────────────────────────────────────── */
.main {
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem 1.5rem 4rem;
}

/* ─── Breadcrumb ────────────────────────────────────────── */
.breadcrumb {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 0 0.375rem;
  font-size: 0.875rem;
  color: var(--color-text-muted);
  margin-bottom: 1.75rem;
}
.breadcrumb li { display: flex; align-items: center; }
.breadcrumb li + li::before { content: "/"; margin-right: 0.375rem; }
.breadcrumb a {
  color: var(--color-accent);
  text-decoration: none;
}
.breadcrumb a:hover { text-decoration: underline; }

/* ─── Preview section ───────────────────────────────────── */
.preview-section {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.preview-figure { display: contents; }

.preview-image-wrap {
  border-radius: var(--radius-lg);
  overflow: hidden;
  border: 1px solid var(--color-border);
  background: var(--color-surface);
  line-height: 0;
}
.preview-placeholder {
  width: 100%;
  height: auto;
  display: block;
  max-height: 480px;
  object-fit: cover;
}

.preview-caption {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.375rem 1rem;
}
.preview-caption__title {
  font-size: 1.25rem;
  font-weight: 600;
}
.preview-caption__meta {
  font-size: 0.875rem;
  color: var(--color-text-muted);
}

/* ─── Action buttons ────────────────────────────────────── */
.preview-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.625rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1.125rem;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 500;
  cursor: pointer;
  text-decoration: none;
  transition: background-color 0.15s, border-color 0.15s, color 0.15s;
  min-height: 44px; /* touch target */
}

.btn--ghost {
  background: var(--color-surface-2);
  border-color: var(--color-border);
  color: var(--color-text);
}
.btn--ghost:hover {
  background: var(--color-surface);
  border-color: var(--color-border-hover);
}

.btn--danger {
  background: var(--color-danger-bg);
  border-color: var(--color-danger);
  color: var(--color-danger);
}
.btn--danger:hover {
  background: var(--color-danger);
  color: #fff;
}

/* ─── Dialog ────────────────────────────────────────────── */
dialog {
  /* Reset browser defaults */
  border: none;
  padding: 0;
  background: transparent;
  /* Ensure hidden when closed */
  display: none;
}
dialog[open] { display: block; }

dialog::backdrop {
  background: rgba(0, 0, 0, 0.72);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
}

.dialog__inner {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-dialog);
  padding: 2rem;
  width: min(480px, calc(100vw - 2rem));
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.dialog__icon {
  color: var(--color-danger);
  align-self: flex-start;
  background: var(--color-danger-bg);
  border-radius: 50%;
  padding: 0.625rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.dialog__heading {
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-text);
}

.dialog__body {
  font-size: 0.9375rem;
  color: var(--color-text-muted);
  line-height: 1.6;
}
.dialog__body strong { color: var(--color-text); }

.dialog__actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.625rem;
  margin-top: 0.5rem;
}

/* ─── Forced colors (high-contrast OS mode) ──────────────── */
@media (forced-colors: active) {
  .btn { border: 2px solid ButtonText; }
  .btn--danger { color: LinkText; border-color: LinkText; }
