const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');

const ids = [...html.matchAll(/id=\"([^\"]+)\"/g)].map(m => m[1]);
const dups = ids.filter((id, i) => ids.indexOf(id) !== i);
if (dups.length) console.log('Duplicate IDs:', dups);
else console.log('IDs OK:', ids.join(', '));

const ariaLabelledby = [...html.matchAll(/aria-labelledby=\"([^\"]+)\"/g)].map(m => m[1]);
ariaLabelledby.forEach(ref => {
  if (!ids.includes(ref)) console.log('Missing aria-labelledby target:', ref);
});
const ariaDescribedby = [...html.matchAll(/aria-describedby=\"([^\"]+)\"/g)].map(m => m[1]);
ariaDescribedby.forEach(ref => {
  if (!ids.includes(ref)) console.log('Missing aria-describedby target:', ref);
});

const buttons = [...html.matchAll(/<button[^>]*>/g)].map(m => m[0]);
const noType = buttons.filter(b => !b.includes('type='));
if (noType.length) console.log('Buttons missing type:', noType);
else console.log('All buttons have type attr');

const hasMain = html.includes('<main');
const hasSkipLink = html.includes('skip-link');
const hasDialogOpen = !html.includes('<dialog[^>]*>') || html.includes('dialog[open]');
console.log('Has main:', hasMain, '| Has skip link:', hasSkipLink);
console.log('Dialog is closed by default (no open attr):', !/<dialog[^>]*open[^>]*>/.test(html));
console.log('Trigger has class trigger:', /class=\"[^\"]*trigger[^\"]*\"/.test(html));
"
