(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // closed-state test
  await page.goto('http://localhost:7788/', { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const r1 = await page.evaluate(async () => await window.axe.run());

  // open dialog, then re-run
  await page.click('#delete-trigger');
  await page.waitForSelector('dialog[open]', { timeout: 5000 });
  const r2 = await page.evaluate(async () => await window.axe.run());

  await browser.close();

  function summarise(r, label) {
    const wcag = r.violations.filter(function(v) { return v.tags.indexOf('best-practice') === -1; });
    const bp   = r.violations.filter(function(v) { return v.tags.indexOf('best-practice') !== -1; });
    return {
      label: label,
      wcag: wcag.map(function(v) { return { id: v.id, impact: v.impact, targets: v.nodes.map(function(n) { return n.target; }) }; }),
      bp:   bp.map(function(v)   { return { id: v.id, targets: v.nodes.map(function(n) { return n.target; }) }; })
    };
  }

  const out = [summarise(r1, 'closed'), summarise(r2, 'dialog-open')];
  console.log(JSON.stringify(out, null, 2));
  const anyWcag = out.some(function(s) { return s.wcag.length > 0; });
  process.exit(anyWcag ? 1 : 0);
})().catch(function(e) { console.error(String(e)); process.exit(2); });
