server.listen(0, '127.0.0.1', async () => {
  const port = server.address().port;
  const base = 'http://127.0.0.1:' + port;

  try {
    const browser = await chromium.launch();
    const page = await browser.newPage();

    // --- test 1: closed state ---
    await page.goto(base + '/', { waitUntil: 'load' });
    await page.addScriptTag({ path: '/tmp/axe.min.js' });
    const r1 = await page.evaluate(async () => await window.axe.run());

    // --- test 2: dialog open ---
    await page.click('#delete-trigger');
    await page.waitForSelector('dialog[open]', { timeout: 5000 });
    const r2 = await page.evaluate(async () => await window.axe.run());

    await browser.close();
    server.close();

    function summarise(r, label) {
      const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
      const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));
      return {
        label,
        wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
        bp:   bp.map(v =>   ({ id: v.id, targets: v.nodes.map(n => n.target) }))
      };
    }

    const results = [summarise(r1, 'closed'), summarise(r2, 'dialog-open')];
    console.log(JSON.stringify(results, null, 2));
    const fail = results.some(s => s.wcag.length > 0);
    process.exit(fail ? 1 : 0);
  } catch (e) {
    server.close();
    console.error(String(e));
    process.exit(2);
  }
});
